export type CompleteReligiousStoryFields = {
  title?: string;
  titleEn?: string;
  brief?: string;
  briefEn?: string;
  transcript?: string;
  transcriptEn?: string;
};

type StoryLookupInput = {
  id?: string;
  title?: string;
  titleEn?: string;
  brief?: string;
};

function text(parts: string[]): string {
  return parts.filter(Boolean).join('\n\n');
}

function normalize(value?: string): string {
  return (value || '')
    .toLowerCase()
    .replace(/[أإآ]/g, 'ا')
    .replace(/ى/g, 'ي')
    .replace(/ؤ/g, 'و')
    .replace(/ئ/g, 'ي')
    .replace(/[ًٌٍَُِّْ]/g, '')
    .trim();
}

